<?php require_once 'functions.php'; require_login(); $title='Pesanan Saya';$id=(int)($_GET['id']??0);if($id){$s=$koneksi->prepare('SELECT p.*,pay.status pay_status,pay.reference,pay.metode FROM pesanan p LEFT JOIN pembayaran pay ON pay.id_pesanan=p.id_pesanan WHERE p.id_pesanan=? AND p.id_user=?');$s->bind_param('ii',$id,$_SESSION['user']['id_user']);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)redirect('pesanan.php');$d=$koneksi->prepare('SELECT d.*,p.nama_produk FROM detail_pesanan d JOIN produk p ON p.id_produk=d.id_produk WHERE d.id_pesanan=?');$d->bind_param('i',$id);$d->execute();$details=$d->get_result();}else{$s=$koneksi->prepare('SELECT p.*,pay.status pay_status,pay.reference FROM pesanan p LEFT JOIN pembayaran pay ON pay.id_pesanan=p.id_pesanan WHERE p.id_user=? ORDER BY p.id_pesanan DESC');$s->bind_param('i',$_SESSION['user']['id_user']);$s->execute();$orders=$s->get_result();}include 'header.php'; ?>
<div class="container"><div class="section-head"><h1><?= $id?'Detail Pesanan #'.$id:'Pesanan Saya' ?></h1><?php if($id):?><a href="pesanan.php">← Semua Pesanan</a><?php endif;?></div><?php if($id):?><div class="panel"><div class="order-head"><div><span class="pill"><?=e(order_status_label($o['status']))?></span><h2>Pesanan #<?=$o['id_pesanan']?></h2></div><div class="right"><b><?=rupiah($o['total'])?></b><small><?=e($o['created_at'])?></small></div></div><p><b>Alamat:</b> <?=e($o['alamat'])?></p><p><b>Pembayaran:</b> <?=e($o['metode'])?> — <?=e(payment_status_label($o['pay_status']??'pending'))?></p><div class="table-wrap"><table><tr><th>Produk</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr><?php while($d=$details->fetch_assoc()):?><tr><td><?=e($d['nama_produk'])?></td><td><?=$d['jumlah']?></td><td><?=rupiah($d['harga'])?></td><td><?=rupiah($d['harga']*$d['jumlah'])?></td></tr><?php endwhile;?></table></div><?php if(($o['pay_status']??'')==='pending'):?><a class="btn" href="pembayaran.php?id=<?=$id?>">Bayar Sekarang</a><?php endif;?></div><?php else:?><div class="table-wrap"><table><tr><th>ID</th><th>Tanggal</th><th>Total</th><th>Pembayaran</th><th>Status</th><th>Aksi</th></tr><?php while($o=$orders->fetch_assoc()):?><tr><td>#<?=$o['id_pesanan']?></td><td><?=e($o['created_at'])?></td><td><?=rupiah($o['total'])?></td><td><?=e(payment_status_label($o['pay_status']??'pending'))?></td><td><span class="status"><?=e(order_status_label($o['status']))?></span></td><td><a href="pesanan.php?id=<?=$o['id_pesanan']?>">Detail</a><?php if(($o['pay_status']??'')==='pending'):?> · <a href="pembayaran.php?id=<?=$o['id_pesanan']?>">Bayar</a><?php endif;?></td></tr><?php endwhile;?></table></div><?php endif;?></div><?php include 'footer.php'; ?>
